get_product_listing.code:
final response = await client.productListing.getProductListing();
final productListing = (response.map as Map)['product_listing'] as Map;
print(productListing['load']);
print(productListing['sorting']);

patch_product_listing.code:
final response = await client.productListing.patchProductListing({
  'product_listing': {
    'sorting': {'enabled': true, 'sort_by': 'price_asc'},
    'load': {
      'pagination': {'per_page': 24},
    },
  },
});
final productListing = (response.map as Map)['product_listing'] as Map;
print(productListing['sorting']);
print(productListing['load']);
